<script setup lang="ts">
import {ref} from 'vue';
import InsuranceSelection from './InsuranceSelection.vue';
import type {ApiClient} from '@kuaixie/sdk';
import {useInsuranceApplication,insuranceStatusKey,insurancePlatformKey} from './useInsurance';
const props=defineProps<{client:ApiClient;orderId:string}>();const p=useInsuranceApplication(props.client,()=>props.orderId);const changeQuote=ref(false);
</script>
<template><section class="business-card"><h3>{{$t('insurance.application')}}</h3><p>{{$t('insurance.boundary')}}</p><p v-if="p.error.value" role="alert">{{p.error.value}}</p><button type="button" :disabled="p.busy.value" @click="p.load">{{$t('common.retry')}}</button><button v-if="!p.application.value" type="button" @click="changeQuote=!changeQuote">{{$t('insurance.requote')}}</button><InsuranceSelection v-if="changeQuote&&!p.application.value" :client="client" subject-type="order" :subject-id="orderId" :item-name="p.risk.value.itemName" :declared-value="p.risk.value.declaredValue" @selected="p.replaceQuote"/><template v-if="p.quote.value"><h4>{{p.quote.value.insurerName}} · {{p.quote.value.productName}}</h4><p>{{$t('insurance.directPremium')}} {{p.quote.value.premium+' '+p.quote.value.currency}}</p><a :href="p.quote.value.termsUrl" target="_blank" rel="noopener noreferrer">{{$t('insurance.terms')}}</a> · <a :href="p.quote.value.exclusionsUrl" target="_blank" rel="noopener noreferrer">{{$t('insurance.exclusions')}}</a><label><input v-model="p.termsAccepted.value" type="checkbox"/>{{$t('insurance.acceptTerms')}}</label><label><input v-model="p.disclosuresAccepted.value" type="checkbox"/>{{$t('insurance.acceptDisclosure')}}</label><button v-if="!p.application.value" type="button" :disabled="p.busy.value" @click="p.apply">{{$t('insurance.apply')}}</button></template><template v-if="p.application.value"><p>{{$t(p.application.value.protectionStatus==='provider_confirmed'?'insurance.effective':'insurance.notIssued')}}</p><p>{{$t(insuranceStatusKey(p.application.value.status))}} · {{p.application.value.policyNumber||''}}</p><a v-if="p.application.value.status==='awaiting_provider'&&p.application.value.checkoutUrl&&p.application.value.platform==='web'" :href="p.application.value.checkoutUrl" target="_blank" rel="noopener noreferrer">{{$t('insurance.payInsurer')}}</a><p v-if="p.application.value.platform!=='web'">{{$t('insurance.platformReturn')}} · {{$t(insurancePlatformKey(p.application.value.platform))}}</p><button type="button" :disabled="p.busy.value" @click="p.refresh">{{$t('insurance.verify')}}</button><a v-if="p.application.value.certificateUrl" :href="p.application.value.certificateUrl" target="_blank" rel="noopener noreferrer">{{$t('insurance.certificate')}}</a> · <a :href="p.application.value.claimsUrl" target="_blank" rel="noopener noreferrer">{{$t('insurance.claims')}}</a><p>{{p.application.value.startsAt}} — {{p.application.value.endsAt}}</p></template></section></template>
